snippets.typescript:
import { SpringSolver, FlipTransition } from '@coheryn/coherynui-motion';

const solver = new SpringSolver({ stiffness: 180, damping: 14, mass: 1 });
const flip = new FlipTransition();

flip.read(element);
// mutate layout
flip.play(element, { spring: solver });

