@layer cyn.recipes {
  .spring-transition {
    transition: transform var(--cyn-spring-duration, 350ms) cubic-bezier(0.16, 1, 0.3, 1);
  }
  @media (prefers-reduced-motion: reduce) {
    .spring-transition {
      transition: none !important;
    }
  }
}
